/** Hand-written DB row shapes (snake_case). Dates are 'YYYY-MM-DD' strings. bigint may arrive as string. */
export type Int8 = number | bigint | string;

export interface TransactionRow {
  id: string;
  seq: Int8;
  trade_date: string;
  symbol: string;
  side: string;
  quantity: number;
  price: number;
  fee: Int8 | null;
  tax: Int8 | null;
  source: 'manual' | 'import';
  import_batch_id: string | null;
  external_ref: string | null;
}

/** Columns written on insert; `seq` is generated by the database. */
export interface TransactionInsert {
  id?: string;
  trade_date: string;
  symbol: string;
  side: 'buy' | 'sell';
  quantity: number;
  price: number;
  fee: number | null;
  tax: number | null;
  source: 'manual' | 'import';
  import_batch_id: string | null;
  external_ref: string | null;
}

export interface CorporateActionRow {
  id: string;
  symbol: string;
  type: string;
  ex_date: string;
  record_date: string | null;
  pay_date: string | null;
  listing_date: string | null;
  amount_per_share: Int8 | null;
  ratio_num: number | null;
  ratio_den: number | null;
}

export interface SettingsRow {
  id: number;
  fee_rate_ppm: number | null;
  sell_tax_rate_ppm: number;
  dividend_withholding_rate_ppm: number;
  settlement_days: number;
  holidays: string[];
  cash_dividend_treatment: string;
  cost_method: string;
}
